<?php
defined( 'ABSPATH' ) || exit;
[ 'groups' => $groups, 'params' => $params, 'bounds' => $bounds, 'sort' => $sort ] = $args;
$currency = html_entity_decode( get_woocommerce_currency_symbol(), ENT_QUOTES, 'UTF-8' );
$slider_max = max( $bounds['max'], (float) ( $params['min_price'] ?? 0 ), (float) ( $params['max_price'] ?? 0 ) );
$decimals = wc_get_price_decimals(); $step = $decimals ? 1 / ( 10 ** $decimals ) : 1;
?>
<form class="vw-catalog-filter-form" data-vw-filter-form method="get" action="<?php echo esc_url( voiceweb_wc_catalog_base_url() ); ?>" data-max="<?php echo esc_attr( $slider_max ); ?>" data-step="<?php echo esc_attr( $step ); ?>">
	<input type="hidden" name="orderby" value="<?php echo esc_attr( $sort ); ?>">
	<?php if ( isset( $params['lang'] ) ) : ?><input type="hidden" name="lang" value="<?php echo esc_attr( $params['lang'] ); ?>"><?php endif; ?>
	<div class="vw-catalog-filter-header"><div><?php echo voiceweb_wc_icon( 'filter' ); ?><h2><?php echo esc_html( cn_translate( 'Filters' ) ); ?></h2></div><button type="button" class="vw-icon-button" data-vw-close-dialog aria-label="<?php echo esc_attr( cn_translate( 'Close' ) ); ?>"><?php echo voiceweb_wc_icon( 'close' ); ?></button><button type="button" class="vw-catalog-clear" data-vw-reset-filters><?php echo esc_html( cn_translate( 'Clear all' ) ); ?></button></div>
	<div class="vw-catalog-filter-body">
		<label class="vw-catalog-search"><span><?php echo esc_html( cn_translate( 'Search products' ) ); ?></span><div><?php echo voiceweb_wc_icon( 'search' ); ?><input type="search" name="vw_search" value="<?php echo esc_attr( $params['vw_search'] ?? '' ); ?>" maxlength="100" placeholder="<?php echo esc_attr( cn_translate( 'Product name or keyword' ) ); ?>" autocomplete="off"></div></label>
		<details class="vw-filter-group" data-group="price" open><summary><?php echo esc_html( cn_translate( 'Price range' ) ); ?><span><?php echo esc_html( $currency ); ?></span><?php echo voiceweb_wc_icon( 'chevron' ); ?></summary><div class="vw-filter-group__body">
			<div class="vw-price-inputs"><label for="vw-price-min"><?php echo esc_html( cn_translate( 'From' ) ); ?><input id="vw-price-min" name="min_price" inputmode="decimal" autocomplete="off" value="<?php echo esc_attr( $params['min_price'] ?? '' ); ?>" placeholder="0" data-vw-price-min><span><?php echo esc_html( $currency ); ?></span></label><label for="vw-price-max"><?php echo esc_html( cn_translate( 'Up to' ) ); ?><input id="vw-price-max" name="max_price" inputmode="decimal" autocomplete="off" value="<?php echo esc_attr( $params['max_price'] ?? '' ); ?>" placeholder="<?php echo esc_attr( cn_localize_digits( number_format_i18n( $bounds['max'], $decimals ) ) ); ?>" data-vw-price-max><span><?php echo esc_html( $currency ); ?></span></label></div>
			<div class="vw-price-slider" data-vw-price-slider><div class="vw-price-slider__track"><i data-vw-price-fill></i></div><input type="range" min="0" max="<?php echo esc_attr( $slider_max ); ?>" step="<?php echo esc_attr( $step ); ?>" value="<?php echo esc_attr( $params['min_price'] ?? 0 ); ?>" aria-label="<?php echo esc_attr( cn_translate( 'Minimum price' ) ); ?>" data-vw-range-min><input type="range" min="0" max="<?php echo esc_attr( $slider_max ); ?>" step="<?php echo esc_attr( $step ); ?>" value="<?php echo esc_attr( $params['max_price'] ?? $slider_max ); ?>" aria-label="<?php echo esc_attr( cn_translate( 'Maximum price' ) ); ?>" data-vw-range-max></div>
			<p class="vw-price-helper"><?php echo esc_html( cn_translate( 'Prices use the store currency shown above.' ) ); ?></p>
		</div></details>
		<div class="vw-filter-switches"><label><span><?php echo esc_html( cn_translate( 'Available products only' ) ); ?></span><input type="checkbox" name="vw_stock" value="1" <?php checked( isset( $params['vw_stock'] ) ); ?>><i aria-hidden="true"></i></label><label><span><?php echo esc_html( cn_translate( 'On sale only' ) ); ?></span><input type="checkbox" name="vw_sale" value="1" <?php checked( isset( $params['vw_sale'] ) ); ?>><i aria-hidden="true"></i></label><label><span><?php echo esc_html( cn_translate( '4 stars and above' ) ); ?></span><input type="checkbox" name="rating_filter" value="4,5" <?php checked( '4,5' === ( $params['rating_filter'] ?? '' ) ); ?>><i aria-hidden="true"></i></label></div>
		<?php foreach ( $groups as $group ) : ?>
			<?php if ( isset( $group['attribute'] ) ) : ?><input type="hidden" name="query_type_<?php echo esc_attr( $group['attribute'] ); ?>" value="<?php echo esc_attr( $params[ 'query_type_' . $group['attribute'] ] ?? 'or' ); ?>"><?php endif; ?>
			<details class="vw-filter-group" data-group="<?php echo esc_attr( $group['key'] ); ?>" <?php echo $group['selected'] || 'vw_category' === $group['key'] ? 'open' : ''; ?>><summary><span><?php echo esc_html( $group['label'] ); ?></span><?php if ( $group['selected'] ) : ?><b><?php echo esc_html( cn_localize_digits( (string) count( $group['selected'] ) ) ); ?></b><?php endif; ?><?php echo voiceweb_wc_icon( 'chevron' ); ?></summary><div class="vw-filter-group__body">
				<?php if ( count( $group['terms'] ) > 7 ) : ?><input class="vw-filter-term-search" type="search" data-vw-term-search aria-label="<?php echo esc_attr( cn_translate( 'Search' ) . ' ' . $group['label'] ); ?>" placeholder="<?php echo esc_attr( cn_translate( 'Search' ) . '…' ); ?>"><?php endif; ?>
				<div class="vw-filter-options"><?php foreach ( $group['terms'] as $term ) : ?><label class="vw-filter-option" data-vw-term-option><input type="checkbox" name="<?php echo esc_attr( $group['key'] ); ?>[]" value="<?php echo esc_attr( $term->slug ); ?>" <?php checked( in_array( $term->slug, $group['selected'], true ) ); ?>><span><?php echo esc_html( $term->name ); ?></span></label><?php endforeach; ?></div>
			</div></details>
		<?php endforeach; ?>
	</div>
	<div class="vw-catalog-filter-footer"><p data-vw-draft-count><?php echo esc_html( cn_translate( 'Choose filters, then show the results.' ) ); ?></p><p class="vw-filter-error" data-vw-filter-error role="status" aria-live="polite" hidden></p><button class="vw-button" type="submit" data-vw-apply-filters><?php echo esc_html( cn_translate( 'Show products' ) ); ?></button><noscript><a href="<?php echo esc_url( voiceweb_wc_catalog_clear_url() ); ?>"><?php echo esc_html( cn_translate( 'Clear all' ) ); ?></a></noscript></div>
</form>
